import { BUSINESS_MAP_UI_CSS, BUSINESS_MAP_UI_JS } from "../business-map/ui-bundle.js";
const safeJson = (value) => JSON.stringify(value).replaceAll("<", "\\u003c");
const esc = (value) => value.replace(/[&<>"']/g, (character) => ({
    "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;",
})[character]);
const impactStatusLabels = {
    added: "新增", modified: "修改", deleted: "删除", renamed: "重命名", copied: "复制",
    type_changed: "类型变更", unmerged: "未合并", unknown: "状态未知",
    pending: "待处理", running: "处理中", completed: "已完成", failed: "失败",
    skipped_no_agent: "未调用 AI", partial: "部分完成", partial_with_failures: "部分完成（有失败）",
    completed_with_failures: "已完成（有失败）",
};
const impactStatusLabel = (value) => impactStatusLabels[value] ?? value;
const renderImpact = (report) => {
    const impact = report.impact;
    if (!impact)
        return '<div class="empty">还没有 Git 变更影响记录。首次运行 <code>code-doctor project update</code> 后在这里查看。</div>';
    const impactUpdatedAt = Date.parse(impact.updatedAt);
    const stale = Boolean((impact.sourceCommit && report.sourceCommit && impact.sourceCommit !== report.sourceCommit)
        || (Number.isFinite(impactUpdatedAt) && report.scenarios.some((scenario) => {
            if (!scenario.map)
                return false;
            const updatedAt = scenario.updatedAt ? Date.parse(scenario.updatedAt) : Number.NaN;
            return Number.isFinite(updatedAt) && updatedAt > impactUpdatedAt;
        })));
    const changed = impact.changedFiles.map((file) => `<li><code>${esc(file.previousPath ? `${file.previousPath} → ${file.path}` : file.path)}</code><span>${esc(impactStatusLabel(file.status))} · ${file.scenarioIds.length ? `关联 ${file.scenarioIds.length} 个场景` : "未归属"}${file.global ? " · 全局" : ""}</span></li>`).join("");
    return `<div class="impact-summary"><div><strong>${impact.changedFiles.length}</strong><span>变更文件</span></div><div><strong>${impact.impactedScenarios.length}</strong><span>受影响场景</span></div><div><strong>${impact.unattributedFiles.length}</strong><span>未归属文件</span></div><div><strong>${impact.unchangedScenarioIds.length}</strong><span>无直接证据关联</span></div></div><p class="context-line"><strong>${stale ? "历史 Git 变更影响（需更新）" : "当前 Git 变更影响"}</strong> · <code>${esc(impact.range)}</code> · ${esc(impactStatusLabel(impact.status))} · 审计${esc(impactStatusLabel(impact.audit.status))}${stale ? " · 结果已过期，需重新更新" : ""}</p><details class="disclosure"><summary>查看变更文件与业务归属</summary><ul class="impact-files">${changed || "<li>该范围没有文件变更。</li>"}</ul></details>`;
};
